/*
 * Mokei design tokens.
 *
 * Values are measured from the Yardline HUD (src/index.css) and the clay
 * diorama palette (src/look.ts). Do not invent a new look here — remap these
 * onto shadcn's semantic names, then add a [data-theme='quarry'] block later.
 */

/*
 * html[data-theme] is more specific than a host app's later :root block
 * (shadcn init writes nova tokens after our import). applyTheme() sets it.
 */
:root,
html[data-theme='yardline'],
[data-theme='yardline'] {
  color-scheme: light;

  /* Typography — SF Pro on Apple, Inter elsewhere (see html.is-apple). */
  --fs: 0.92;
  --track: -0.012em;

  /* Ink + chrome from the existing HUD */
  --ink: #0f172a;
  --ink-2: #1e293b;
  --muted: #64748b;
  --muted-2: #94a3b8;
  --hair: rgba(203, 213, 225, 0.6);
  --blue: #2563eb;
  --blue-deep: #1d4ed8;

  --glass-bg: rgba(255, 255, 255, 0.9);
  --glass-border: rgba(255, 255, 255, 0.95);
  --glass-shadow: 0 1px 2px rgba(30, 41, 90, 0.04), 0 8px 24px rgba(30, 41, 90, 0.08);
  --glass-blur: 20px;
  --glass-saturate: 1.35;
  --topbar-bg: rgba(248, 250, 255, 0.78);
  --topbar-border: rgba(214, 222, 238, 0.7);
  --topbar-shadow: 0 6px 20px rgba(30, 41, 90, 0.04);

  /* shadcn semantic tokens, mapped onto the HUD — not a new palette */
  --background: #e9eef8;
  --foreground: #0f172a;
  --card: rgba(255, 255, 255, 0.9);
  --card-foreground: #0f172a;
  --popover: rgba(255, 255, 255, 0.96);
  --popover-foreground: #0f172a;
  --primary: #2563eb;
  --primary-foreground: #ffffff;
  --secondary: #e9eefc;
  --secondary-foreground: #1e293b;
  --muted-surface: #eef1f5;
  --muted-foreground: #64748b;
  --accent: #dbeafe;
  --accent-foreground: #1d4ed8;
  --destructive: #ef4444;
  --border: rgba(203, 213, 225, 0.6);
  --input: #dde3ee;
  --ring: #2563eb;

  /* 12px is the HUD control radius (search, site, KPI tiles). */
  --radius: 0.75rem;

  --success: #15803d;
  --success-foreground: #dcf5e3;
  --warning: #c2620a;
  --warning-foreground: #fdefd3;
  --info: #1d4ed8;
  --info-foreground: #d9e5fe;

  --chart-1: #2563eb;
  --chart-2: #22c55e;
  --chart-3: #f2c14e;
  --chart-4: #e0b17a;
  --chart-5: #72d39c;

  --sidebar: rgba(248, 250, 255, 0.78);
  --sidebar-foreground: #0f172a;
  --sidebar-primary: #2563eb;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #e9eefc;
  --sidebar-accent-foreground: #1e293b;
  --sidebar-border: rgba(214, 222, 238, 0.7);
  --sidebar-ring: #2563eb;

  /* Clay diorama materials from lookDefaults */
  --clay-ground: #e9eef8;
  --clay-road: #c4d0f2;
  --clay-grass: #dcf4e6;
  --clay-wall: #f7f9fd;
  --clay-roof: #2f63e6;
  --clay-accent: #2563eb;
  --clay-yellow: #f2c14e;
  --clay-cardboard: #e0b17a;
  --clay-tree: #72d39c;
  --clay-tire: #1f2533;
  --clay-ao: #25335a;
  --clay-sky: #e9efff;
}

/*
 * Dark is the same glass + clay language for now. A future dusk or quarry
 * theme should override [data-theme] rather than invent values here.
 */
.dark {
  --background: #e9eef8;
  --foreground: #0f172a;
  --card: rgba(255, 255, 255, 0.9);
  --card-foreground: #0f172a;
  --popover: rgba(255, 255, 255, 0.96);
  --popover-foreground: #0f172a;
  --primary: #2563eb;
  --primary-foreground: #ffffff;
  --secondary: #e9eefc;
  --secondary-foreground: #1e293b;
  --muted-surface: #eef1f5;
  --muted-foreground: #64748b;
  --accent: #dbeafe;
  --accent-foreground: #1d4ed8;
  --destructive: #ef4444;
  --border: rgba(203, 213, 225, 0.6);
  --input: #dde3ee;
  --ring: #2563eb;
  --sidebar: rgba(248, 250, 255, 0.78);
  --sidebar-foreground: #0f172a;
  --sidebar-primary: #2563eb;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #e9eefc;
  --sidebar-accent-foreground: #1e293b;
  --sidebar-border: rgba(214, 222, 238, 0.7);
  --sidebar-ring: #2563eb;
}

html.is-apple {
  --fs: 1;
  --track: -0.003em;
}

/*
 * Consumer-facing Tailwind v4 preset (git dependency + shadcn registry).
 * The playground keeps using preset.css so its HUD-specific base layer stays put.
 */

@import './tokens.css';

@custom-variant dark (&:is(.dark *));

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted-surface);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);
  --color-success: var(--success);
  --color-success-foreground: var(--success-foreground);
  --color-warning: var(--warning);
  --color-warning-foreground: var(--warning-foreground);
  --color-info: var(--info);
  --color-info-foreground: var(--info-foreground);
  --color-ink: var(--ink);
  --color-ink-2: var(--ink-2);
  --color-hair: var(--hair);
  --color-blue: var(--blue);
  --color-blue-deep: var(--blue-deep);
  --color-clay-ground: var(--clay-ground);
  --color-clay-road: var(--clay-road);
  --color-clay-grass: var(--clay-grass);
  --color-clay-wall: var(--clay-wall);
  --color-clay-roof: var(--clay-roof);
  --color-clay-yellow: var(--clay-yellow);
  --color-clay-cardboard: var(--clay-cardboard);
  --color-clay-tree: var(--clay-tree);

  --radius-sm: calc(var(--radius) * 0.66);
  --radius-md: calc(var(--radius) * 0.83);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) * 1.33);
  --radius-2xl: calc(var(--radius) * 1.8);
  --radius-3xl: calc(var(--radius) * 2.2);
  --radius-4xl: calc(var(--radius) * 2.6);

  --shadow-glass: var(--glass-shadow);
  --blur-glass: var(--glass-blur);
}

@utility glass-panel {
  background: var(--glass-bg);
  /* Match main's LightningCSS output: -webkit only, so Linux Chrome does
   * not frost the scene behind HUD glass. */
  -webkit-backdrop-filter: blur(var(--glass-blur)) saturate(var(--glass-saturate));
  border: 1px solid var(--glass-border);
  box-shadow: var(--glass-shadow);
}
